		Session.Prompt( "Select a Class or Enumeration element to export attributes." , promptOK);
	}
	ExportAttributes(theSelectedElement);
}

// Выгрузка атрибутов указанного класса
function ExportAttributes( pClass ){
	var theClass as EA.Element;
	theClass = pClass;
	PrintHeaderList();
	for (var i=0; i < theClass.Attributes.Count; i++){
		PrintAttributeList(i+1, theClass.Attributes.GetAt(i));
	}
}

function PrintHeaderHtml(){
	Session.Output("<tr>");
	Session.Output("<td>"+"Name"+"</td><td>"+"Type"+"</td><td>"+"Alias"+"</td><td>"+"Notes"+"</td>");
//	Session.Output("|"+"Name"+"|"+"Type"+"|"+"Alias"+"|"+"Notes"+"|");
	Session.Output("</tr>");
}

function PrintAttributeHtml( pAttribute){
	var attribute as EA.Attribute;
	attribute = pAttribute;
	Session.Output("<tr>");
	Session.Output("<td>"+attribute.Name +"</td><td>"+attribute.Type+"</td><td>"+attribute.Alias+"</td><td>"+attribute.Notes+"</td>");
//		Session.Output("|"+attribute.Name +"|"+attribute.Type+"|"+attribute.Alias+"|"+attribute.Notes+"|");
	Session.Output("</tr>");
}

function PrintHeaderList(){
}

function PrintAttributeList( index, pAttribute ){
	var attribute as EA.Attribute;
	attribute = pAttribute;
	var description = [(attribute.Stereotype ? "Stereotype: "+attribute.Stereotype : null), attribute.Alias, attribute.Notes].filter(i => i).map(i => (i.trim().slice(-1) != "." ? i.trim()+"." : i)).join(" ");
	var stringType = attribute.Type;
	if (attribute.LowerBound != "1" || attribute.UpperBound != "1") {
		stringType = attribute.Type + "[" + attribute.LowerBound + ".." + attribute.UpperBound + "]";
	}
	Session.Output(index + ". " + attribute.Name +": " + stringType + (description ? " (" + description + ")": ""));
}

OnItemScript();

