// Определение слеша по строке для совместимости с MacOS
function GetSlash( samplePath ){
	if (samplePath.includes("/")) {
		return "/";
	} else {
		return "\\"
	}
}


// Формирование пути к файлу на основе двух частей
function MakeFilePath( first, second ){
	return (first.trim().slice(-1) != GetSlash(first) ? first.trim() + GetSlash(first) : first.trim()) + second;
}

!INC Local Scripts.EAConstants-JavaScript

/*
 * Script Name: 
 * Author: 
 * Purpose: 
 * Date: 
 */

// Get property type value from global project options
function GetPropertyTypeValue( name ) {
	Repository.PropertyTypes.Refresh();
	for (var i=0; i < Repository.PropertyTypes.Count; i++){
		var propertyType as EA.PropertyType;
		propertyType = Repository.PropertyTypes.GetAt(i);
		if (propertyType.Tag == name) {
			return propertyType.Detail;
		}
	}
	return "";
}

// Set property type value to global project options
function SetPropertyTypeValue( name, value, description ) {
	var foundPropertyType as EA.PropertyType;
	foundPropertyType = null;
	for (var i=0; i < Repository.PropertyTypes.Count; i++){
		var propertyType as EA.PropertyType;
		propertyType = Repository.PropertyTypes.GetAt(i);
		if (propertyType.Tag == name) {
			foundPropertyType = propertyType;
		}
	}
	if (!foundPropertyType) {
		var newPropertyType as EA.PropertyType;
		newPropertyType = Repository.PropertyTypes.AddNew(name, description);
		newPropertyType.Description = description;
		newPropertyType.Detail = value;
		newPropertyType.Update();
	} else {
		foundPropertyType.Detail = value;
		foundPropertyType.Update();
	}
	Repository.PropertyTypes.Refresh();
}

!INC Local Scripts.EAConstants-JavaScript
!INC Utils.File-Utils

/*
 * Script Name: ExportDiagrams.ExportDiagrams-Helper
 * Author: Sergey Gaidamakov
 * Purpose: Вспомогательные функции для выгрузки диаграмм.
 * Date: 13.12.2024
 */

var ELEMENT_TYPES_WITH_DIAGRAMS = ["Class", "Interface", "Component", "StateMachine", "UseCase", "Requirement", "Feature", "Actor", "Activity", "Interaction"];

function IsDeletedDiagram( aDiagram ) {
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	return theDiagram.Name.slice(0,1) == "-";
}

function IsDeletedPackage( aPackage ) {
	var thePackage as EA.Package;
	thePackage = aPackage;
	return thePackage.Name.slice(0,1) == "-";
}

function IsDeletedElement( anElement ) {
	var theElement as EA.Element;
	theElement = anElement;
	if (!theElement.Name) {
		LOGTrace("IsDeletedElement !theElement.Name = "+theElement.Type);
		return false;
	}
	return theElement.Name.slice(0,1) == "-";
}

function GetDiagramFileName( aDiagram ) {
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	return theDiagram.DiagramGUID.slice(1,-1) + ".png";
}


function GetDiagramVersionFileName( aDiagram ){
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	return theDiagram.DiagramGUID.slice(1,-1) + "_" + theDiagram.Version.replace(".", "_") + ".png";
}


function GetDiagramFullFileName( anExportPath, aDiagram ) {
	return MakeFilePath( anExportPath, "EA" + GetSlash(anExportPath) + "Diagrams" + GetSlash(anExportPath) + GetDiagramFileName( aDiagram ));
}


function GetDiagramFullVersionFileName( anExportPath, aDiagram ) {
	return MakeFilePath( anExportPath, "EA" + GetSlash(anExportPath) + "Diagrams" + GetSlash(anExportPath) + GetDiagramVersionFileName( aDiagram ));
}

function GetDiagramGitFileName( aGitProjectPath, aDiagram ) {
	return MakeFilePath( aGitProjectPath, GetDiagramFileName(aDiagram));
}


function GetDiagramGitVersionFileName( aGitProjectPath, aDiagram ) {
	return MakeFilePath( aGitProjectPath, GetDiagramVersionFileName(aDiagram));
}


//function GetPackagePath( aPackage ) {
//	if (!aPackage) {
//		return "";
//	}
//	var thePackage as EA.Package;
//	thePackage = aPackage;
//	if (thePackage.ParentID) {
//		var theParentPackage as EA.Package;
//		var theParentPackage = Repository.GetPackageByID(thePackage.ParentID);
//		return GetPackagePath(theParentPackage) + " \\ " + thePackage.Name;
//	}
//	return thePackage.Name;
//}


function GetElementPath( anElement ) {
	if (!anElement) {
		return "";
	}
	var theElement as EA.Element;
	theElement = anElement;
	if (theElement.ParentID) {
		if (theElement.Type) {
			var theParentElement as EA.Element;
			var theParentElement = Repository.GetElementByID(theElement.ParentID);
			return GetElementPath(theParentElement) + " \\ " + theElement.Name;
		} else {
			var theParentPackage as EA.Package;
			var theParentPackage = Repository.GetPackageByID(theElement.ParentID);
			return GetElementPath( theParentPackage ) + " \\ " + theElement.Name;
		}
	}
	if (theElement.PackageID && theElement.Type) {
		// У верхнего элемента нет ParentID и нет theElement.Type, чтобы не зациклились
		var theParentPackage as EA.Package;
		var theParentPackage = Repository.GetPackageByID(theElement.PackageID);
		return GetElementPath( theParentPackage ) + " \\ " + theElement.Name;
	}
	return theElement.Name;
}


function GetDefaultExportPathPropertyName() {
	return "DiagramExportPath";
}


function GetUserExportPathPropertyName() {
	return (Session.UserName ? Session.UserName + "_" + GetDefaultExportPathPropertyName() : GetDefaultExportPathPropertyName());
}


function GetDefaultGitProjectPropertyName() {
	return "DocumentationGitProject";
}


function GetUserGitProjectPropertyName() {
	return (Session.UserName ? Session.UserName + "_" + GetDefaultGitProjectPropertyName() : GetDefaultGitProjectPropertyName());
}


function ExportDiagramsFromPackage( aProject, anExportPath, aGitProjectPath, aPackage ) {
	var thePackage as EA.Package;
	var diagramCount = 0;
	thePackage = aPackage;
	var packagePath = GetPackagePath( thePackage );

	if (IsDeletedPackage(thePackage)) {
		Session.Output( " " );
		Session.Output( "Package is deleted: " + packagePath );
		Session.Output( " " );
		return 0;
	}

	for (var i=0; i < thePackage.Diagrams.Count; i++){
		diagramCount += ExportDiagram( aProject, anExportPath, aGitProjectPath, packagePath, thePackage.Diagrams.GetAt(i) );
	}
	for (var i=0; i < thePackage.Elements.Count; i++){
		diagramCount += ExportDiagramsFromElement( aProject, anExportPath, aGitProjectPath, packagePath, thePackage.Elements.GetAt(i) );
	}
	for (var i=0; i < thePackage.Packages.Count; i++){
		diagramCount += ExportDiagramsFromPackage( aProject, anExportPath, aGitProjectPath, thePackage.Packages.GetAt(i) );
	}
	return diagramCount;
}


function ExportDiagramsFromElement( aProject, anExportPath, aGitProjectPath, anElement ) {
	var theElement as EA.Element;
	var diagramCount = 0;
	theElement = anElement;
	if (!theElement) {
		LOGTrace("!!! Function ExportDiagramsFromElement has got theElement == null.");
		return 0;
	}
	if (theElement.Type && !ELEMENT_TYPES_WITH_DIAGRAMS.includes(theElement.Type)){
		LOGTrace("Element <" + theElement.Name + "> has skipped type " + theElement.Type);
		return 0;
	}
	var elementPath = GetElementPath( theElement );
	if (IsDeletedElement(theElement)) {
		Session.Output( " " );
		Session.Output( "Element is deleted: " + elementPath );
		Session.Output( " " );
		return 0;
	}
	if (theElement.Diagrams) {
		for (var i=0; i < theElement.Diagrams.Count; i++){
			diagramCount += ExportDiagram( aProject, anExportPath, aGitProjectPath, elementPath, theElement.Diagrams.GetAt(i) );
		}
	}
	if (theElement.Elements) {
		for (var i=0; i < theElement.Elements.Count; i++){
			diagramCount += ExportDiagramsFromElement( aProject, anExportPath, aGitProjectPath, theElement.Elements.GetAt(i) );
		}
	}
	if (theElement.Packages) {
		for (var i=0; i < theElement.Packages.Count; i++){
			diagramCount += ExportDiagramsFromElement( aProject, anExportPath, aGitProjectPath, theElement.Packages.GetAt(i) );
		}
	}
	return diagramCount;
}


function ExportDiagram( aProject, anExportPath, aGitProjectPath, aPackagePath, aDiagram, keepOpenedDiagrams ) {
	var theDiagram as EA.Diagram;
	theDiagram = aDiagram;
	var diagramPath = aPackagePath + " \\ " + theDiagram.Name;

	if (IsDeletedDiagram(theDiagram)) {
		Session.Output( "Diagram is deleted: " + diagramPath );
		return 0;
	}
	// Remember the visibility of the diagram
	var diagramIsVisible = keepOpenedDiagrams || Repository.IsTabOpen(theDiagram.Name.slice(0,30)) == 2;

	var theProject as EA.Project;
	theProject = aProject;
	var fileName = GetDiagramFullFileName( anExportPath, theDiagram );
	var versionFileName = GetDiagramFullVersionFileName( anExportPath, theDiagram );

	if (!theProject.PutDiagramImageToFile(theDiagram.DiagramGUID, fileName, 1)) {
		var errorMessage = "Can not export diagram <"+diagramPath+"> to file <"+fileName+">: "+GetLastError();
		LOGError(errorMessage);
		return 0;

	}
	if (!theProject.PutDiagramImageToFile(theDiagram.DiagramGUID, versionFileName, 1)) {
		var errorMessage = "Can not export diagram <"+diagramPath+"> to version file <"+versionFileName+">: "+GetLastError();
		LOGError(errorMessage);
		return 0;

	}
	// Удаление из описания диаграммы старой информации:
	var notes = theDiagram.Notes;
	var newDiagramNotes = "";
	var DIAGRAM_INFO_TOKEN = "\r\n#####";
	var startIndex = notes.indexOf(DIAGRAM_INFO_TOKEN);
	var endIndex = notes.slice(startIndex + DIAGRAM_INFO_TOKEN.length).indexOf(DIAGRAM_INFO_TOKEN);
	if (endIndex >= 0) {
		endIndex += startIndex + DIAGRAM_INFO_TOKEN.length + DIAGRAM_INFO_TOKEN.length;
	}
	if (startIndex >= 0) {
		newDiagramNotes += notes.slice(0, startIndex);
	} else {
		newDiagramNotes = notes;
	}
	if (endIndex >= 0) {
		newDiagramNotes += notes.slice(endIndex);
	}
	// Подготовка и обновление новой информации для диаграммы:
	var diagramInfo = DIAGRAM_INFO_TOKEN;
	diagramInfo += "\r\n<b>Export date:</b> " + (new Date()).toLocaleString('ru-RU'); // toLocaleDateString('ru-RU');
	diagramInfo += "\r\n<b>File name:</b> " + GetDiagramFileName( theDiagram );
	if (aGitProjectPath) {
		diagramInfo += "\r\n<b>Main Git:</b> " + GetDiagramGitFileName( aGitProjectPath, theDiagram );
		diagramInfo += "\r\n<b>Version Git:</b> " + GetDiagramGitVersionFileName( aGitProjectPath, theDiagram );
	}
	diagramInfo += DIAGRAM_INFO_TOKEN;
	theDiagram.Notes = newDiagramNotes + diagramInfo;
	if (!theDiagram.Update()) {
		Session.Output("ERROR Diagram update <"+diagramPath+">:"+theDiagram.GetLastError());
	}

	if (!diagramIsVisible) {
		// При сохранении в файл открывается закладка диаграммы и ее нужно закрыть:
		Repository.CloseDiagram(theDiagram.DiagramID);
	} else {
		// Нужно обновить диаграмму на экране, чтобы увидеть обновленные ссылки
		// Внимание!!! theDiagram.ModifiedDate не меняется, поэтому Diagram Notes тоже не обновляет дату изменения :( 
		// Возможно то и к лучшему, так как на диаграмме по факту ничего, кроме описания не меняется.
		Repository.ReloadDiagram(theDiagram.DiagramID);
	}

	Session.Output("Diagram <"+diagramPath+"> has been exported to files:");
	Session.Output("   "+fileName);
	Session.Output("   "+versionFileName);
	return 1;
}

!INC Local Scripts.EAConstants-JavaScript
!INC EAScriptLib.JavaScript-Logging
!INC ExportDiagrams.ExportDiagrams-Helper
!INC Utils.PropertyType-Utils

/*
 * Script Name: Browser Scripts.Export Diagrams
 * Author: Sergey Gaidamakov
 * Purpose: Выгрузка картинки выбранной диаграммы в каталог
 * Date: 13.12.2024
 */

// LOGLEVEL = LOGLEVEL_ERROR;
// LOGLEVEL = LOGLEVEL_INFO;
// LOGLEVEL = LOGLEVEL_WARNING;
// LOGLEVEL = LOGLEVEL_DEBUG;
LOGLEVEL = LOGLEVEL_TRACE;

function OnDiagramScript()
{
	Repository.EnsureOutputVisible( "Script" );
	Repository.ClearOutput("Script");

	Session.Output( "Session.UserName = " + Session.UserName);

	var exportPath = GetPropertyTypeValue( GetUserExportPathPropertyName() );
	if (!exportPath) {
		// Если не нашли путь, специфичный для текущего пользователя, то берем путь по умолчанию.
		exportPath = GetPropertyTypeValue( GetDefaultExportPathPropertyName() );
		LOGTrace("exportPath from <"+GetDefaultExportPathPropertyName() + "> = " + exportPath);
	}
	if (!exportPath) {
		Session.Prompt( "Not found 'Tagged value type' with name <"+GetDefaultExportPathPropertyName()+">. Define tagged value <"+GetDefaultExportPathPropertyName()+"> at menu 'Settings \\ Reference Data \\ UML Types'", promptOK );
		return;
	}
	var result = Session.Prompt("Export diagrams to path '"+exportPath+"'" , promptYESNO);
	if (result != resultYes) {
		exportPath = Session.Input("Enter export diagrams path");
		if (!exportPath) {
			return;
		}
		// Сохраняем новое значение пути
		SetPropertyTypeValue( GetUserExportPathPropertyName(), exportPath, "Путь для экспорта диаграмм" );
		LOGTrace("exportPath saved to <"+GetUserExportPathPropertyName() + "> = " + exportPath);
	}
	Session.Output("exportPath = " + exportPath);

	// gitProjectPath для данной функции может не задано.
	var gitPropertyName = GetUserGitProjectPropertyName();
	Session.Output("gitPropertyName = " + gitPropertyName);
	var gitProjectPath = GetPropertyTypeValue( GetUserGitProjectPropertyName() );
	if (gitProjectPath) {
		Session.Output("gitProjectPath = " + gitProjectPath);
	} else {
		Session.Output("gitProjectPath is empty");
	}
	Session.Output( " " );

	// Get the type of element selected in the Project Browser
	var myProject as EA.Project;
	myProject = Repository.GetProjectInterface();
	var countDiagrams = 0;

	// Get a reference to the current diagram
	var currentDiagram as EA.Diagram;
	currentDiagram = Repository.GetCurrentDiagram();

	if (!currentDiagram)
	{
		Session.Prompt( "Open a Diagram to export its picture.", promptOK)
		return;
	}
	var diagramPath = "";
	var theElement as EA.Element;
	theElement = Repository.GetElementByID( currentDiagram.ParentID );
	if (theElement) {
		diagramPath = GetElementPath( theElement );
	} else {
		var thePackage as EA.Package;
		var thePackage = Repository.GetPackageByID(currentDiagram.PackageID);
		diagramPath = GetElementPath( thePackage );
	}
	countDiagrams = ExportDiagram(myProject, exportPath, gitProjectPath, diagramPath, currentDiagram, true);
	Session.Prompt( countDiagrams + " diagrams has been exported.", promptOK );
}

OnDiagramScript();
